import
{
    Routes
}
from '@angular/router';

// Product Ledgers : one shared page; data.ledgerType (MB / SP /
// AC) picks the product type


//===========================================================
// MNU-012-006 Routes
//===========================================================

export const mnu012006Routes:
Routes =
[


    //===========================================================
    // Menu Routes
    //===========================================================
    // Auto-generated by Menu Synchronization Engine.
    // Submenu Synchronization Engine will register:
    //   • Submenu routes
    //   • Activity routes
    //   • Page routes
    //===========================================================


    {
        path:'',

        children:
        [

            // SUBMENU ROUTE PLACEHOLDER

            //===========================================================
            // Motor Bikes Ledger (hand-written : read-only page, no Code Sync)
            //===========================================================

            {
                path:'motor-bikes-ledger',

                data:
                {
                    breadcrumb:'Motor Bikes Ledger',

                    ledgerType:'MB'
                },

                loadComponent:() =>
                    import(
                        '../pages/product-ledger/product-ledger'
                    )
                    .then(
                        m =>
                            m.ProductLedger
                    )
            },

            //===========================================================
            // Spare Parts & Lubricants Ledger (hand-written : read-only page, no Code Sync)
            //===========================================================

            {
                path:'spare-parts-lubricants-ledger',

                data:
                {
                    breadcrumb:'Spare Parts & Lubricants Ledger',

                    ledgerType:'SP'
                },

                loadComponent:() =>
                    import(
                        '../pages/product-ledger/product-ledger'
                    )
                    .then(
                        m =>
                            m.ProductLedger
                    )
            },

            //===========================================================
            // Accessories Ledger (hand-written : read-only page, no Code Sync)
            //===========================================================

            {
                path:'accessories-ledger',

                data:
                {
                    breadcrumb:'Accessories Ledger',

                    ledgerType:'AC'
                },

                loadComponent:() =>
                    import(
                        '../pages/product-ledger/product-ledger'
                    )
                    .then(
                        m =>
                            m.ProductLedger
                    )
            },

        ]

    }

];